/**
 * Calendar Daily Agenda.
 *
 * Emails tomorrow's calendar events to one recipient.
 * Defaults to the script owner's own email address, so nothing
 * personal is hardcoded.
 *
 * Script Properties (Project Settings > Script Properties):
 *   AGENDA_RECIPIENT - email address (default: active user's email)
 *   AGENDA_CALENDAR  - calendar ID (default: primary calendar)
 */

function sendDailyAgenda() {
  var props = PropertiesService.getScriptProperties();
  var recipient = props.getProperty('AGENDA_RECIPIENT') ||
    Session.getActiveUser().getEmail();
  var calendarId = props.getProperty('AGENDA_CALENDAR') || 'primary';

  var tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  var start = new Date(tomorrow.getFullYear(), tomorrow.getMonth(), tomorrow.getDate());
  var end = new Date(tomorrow.getFullYear(), tomorrow.getMonth(), tomorrow.getDate() + 1);

  var calendar = CalendarApp.getCalendarById(calendarId);
  var events = calendar.getEvents(start, end);
  var lines = events.map(function (event) {
    return formatEvent(event);
  });

  var dateLabel = Utilities.formatDate(start, Session.getScriptTimeZone(), 'EEEE, MMMM d');
  var subject = 'Agenda for ' + dateLabel;
  var body = lines.length === 0 ?
    'No events tomorrow (' + dateLabel + ').' :
    'Agenda for ' + dateLabel + ':\n\n' + lines.join('\n');
  GmailApp.sendEmail(recipient, subject, body);
  Logger.log(body);
}

function formatEvent(event) {
  var start = Utilities.formatDate(event.getStartTime(), Session.getScriptTimeZone(), 'h:mm a');
  var title = event.getTitle();
  if (event.isAllDayEvent()) {
    return 'All day: ' + title;
  }
  return start + ' - ' + title;
}

/**
 * Drive File Organizer.
 *
 * Moves files from one folder into subfolders by type:
 * Documents, Spreadsheets, Presentations, Images, PDFs, Other.
 *
 * Script Properties (Project Settings > Script Properties):
 *   SOURCE_FOLDER_ID - Drive folder ID to organize (required)
 *   DRY_RUN          - "true" (default) logs only; "false" moves files
 *
 * Subfolders are created inside the source folder on first use.
 * Files already in a subfolder are left alone: only the top level
 * of the source folder is scanned.
 */

function organizeDriveFolder() {
  var props = PropertiesService.getScriptProperties();
  var folderId = props.getProperty('SOURCE_FOLDER_ID');
  if (!folderId) {
    throw new Error('Set the SOURCE_FOLDER_ID Script Property first.');
  }
  var dryRun = props.getProperty('DRY_RUN') !== 'false';

  var folder = DriveApp.getFolderById(folderId);
  var files = folder.getFiles();
  var moved = 0;
  while (files.hasNext()) {
    var file = files.next();
    var category = categoryForMimeType(file.getMimeType());
    if (dryRun) {
      Logger.log('[DRY RUN] Would move "' + file.getName() + '" to ' + category);
    } else {
      var target = getOrCreateSubfolder(folder, category);
      file.moveTo(target);
    }
    moved++;
  }
  Logger.log('Done. Files considered: ' + moved + '. Dry run: ' + dryRun);
}

function categoryForMimeType(mimeType) {
  if (mimeType === MimeType.GOOGLE_DOCS) return 'Documents';
  if (mimeType === MimeType.GOOGLE_SHEETS) return 'Spreadsheets';
  if (mimeType === MimeType.GOOGLE_SLIDES) return 'Presentations';
  if (mimeType === MimeType.PDF) return 'PDFs';
  if (mimeType.indexOf('image/') === 0) return 'Images';
  return 'Other';
}

function getOrCreateSubfolder(folder, name) {
  var existing = folder.getFoldersByName(name);
  if (existing.hasNext()) {
    return existing.next();
  }
  return folder.createFolder(name);
}

/**
 * Gmail Inbox Triage.
 *
 * Labels threads matching a search query, and optionally archives them.
 * Dry-run is ON by default: set the DRY_RUN Script Property to "false"
 * only when you are ready for it to change labels.
 *
 * Script Properties (Project Settings > Script Properties):
 *   TRIAGE_QUERY  - Gmail search query, e.g. "is:unread older_than:7d"
 *                   (default: "is:unread older_than:7d")
 *   TRIAGE_LABEL  - label to apply, e.g. "To Review" (default: "To Review")
 *   ARCHIVE_AFTER - "true" to archive labelled threads (default: "false")
 *   DRY_RUN       - "true" (default) logs only; "false" applies changes
 */

function triageInbox() {
  var props = PropertiesService.getScriptProperties();
  var query = props.getProperty('TRIAGE_QUERY') || 'is:unread older_than:7d';
  var labelName = props.getProperty('TRIAGE_LABEL') || 'To Review';
  var archiveAfter = props.getProperty('ARCHIVE_AFTER') === 'true';
  var dryRun = props.getProperty('DRY_RUN') !== 'false';

  var label = dryRun ? null : GmailApp.getUserLabelByName(labelName) ||
    GmailApp.createLabel(labelName);

  var threads = GmailApp.search(query, 0, 100);
  Logger.log('Found ' + threads.length + ' thread(s) for query: ' + query);

  threads.forEach(function (thread) {
    var subject = thread.getFirstMessageSubject();
    if (dryRun) {
      Logger.log('[DRY RUN] Would label "' + subject + '" with "' + labelName + '"' +
        (archiveAfter ? ' and archive it.' : '.'));
      return;
    }
    thread.addLabel(label);
    if (archiveAfter) {
      thread.moveToArchive();
    }
  });

  Logger.log('Done. Dry run: ' + dryRun);
}

/**
 * Sheet Weekly Report.
 *
 * Reads rows from a spreadsheet and emails a short summary:
 * row count, and the sum of a numeric column when one is configured.
 *
 * Script Properties (Project Settings > Script Properties):
 *   REPORT_SPREADSHEET_ID - spreadsheet ID (required, never hardcoded)
 *   REPORT_SHEET_NAME     - sheet/tab name (default: first sheet)
 *   REPORT_AMOUNT_COLUMN  - 1-based column to sum, e.g. "3" (optional)
 *   REPORT_RECIPIENT      - email address for the report (required)
 *
 * The first row is treated as a header and is not counted or summed.
 */

function sendWeeklyReport() {
  var props = PropertiesService.getScriptProperties();
  var spreadsheetId = props.getProperty('REPORT_SPREADSHEET_ID');
  var recipient = props.getProperty('REPORT_RECIPIENT');
  if (!spreadsheetId) {
    throw new Error('Set the REPORT_SPREADSHEET_ID Script Property first.');
  }
  if (!recipient) {
    throw new Error('Set the REPORT_RECIPIENT Script Property first.');
  }

  var spreadsheet = SpreadsheetApp.openById(spreadsheetId);
  var sheetName = props.getProperty('REPORT_SHEET_NAME');
  var sheet = sheetName ? spreadsheet.getSheetByName(sheetName) :
    spreadsheet.getSheets()[0];
  if (!sheet) {
    throw new Error('Sheet not found: ' + sheetName);
  }

  var values = sheet.getDataRange().getValues();
  var summary = summarizeRows(values, props.getProperty('REPORT_AMOUNT_COLUMN'));

  var subject = 'Weekly report: ' + spreadsheet.getName();
  var body = 'Rows (excluding header): ' + summary.rowCount + '\n' +
    (summary.total !== null ? 'Total: ' + summary.total + '\n' : '') +
    'Sheet: ' + sheet.getName() + '\n';
  GmailApp.sendEmail(recipient, subject, body);
  Logger.log(body);
}

/**
 * Pure summary helper, kept separate so its logic is easy to reason
 * about: header row excluded, non-numeric cells ignored in the total.
 */
function summarizeRows(values, amountColumn) {
  if (!values || values.length < 2) {
    return { rowCount: 0, total: null };
  }
  var rows = values.slice(1);
  var total = null;
  if (amountColumn) {
    var columnIndex = parseInt(amountColumn, 10) - 1;
    total = 0;
    rows.forEach(function (row) {
      var value = Number(row[columnIndex]);
      if (!isNaN(value)) {
        total += value;
      }
    });
  }
  return { rowCount: rows.length, total: total };
}
